template<class T> void debug_output(const char *s, T h){ cerr << s << " = " << h << endl; }
template<class T, class... Args> void debug_output(const char *s, T h, Args... a) {
  while(*s != ',') cerr << *s++;
  cerr << " = " << h << ", "; debug_output(s+1, a...);
}

#ifdef LOCAL
#define debug(...) debug_output(#__VA_ARGS__, __VA_ARGS__)
