const int MAXN = (1<<20)+7;
const int MAXK = 20;
const int INF = (1e9)+7;
const LL LLINF = ((LL)1e18)+7LL;
const LD EPS = 1e-9;
const LL MOD = 1e9+7;

int grid_vals_alt[MAXK][MAXK];
int elo_map_vals_alt[MAXK][MAXK];
int mask_map_vals_alt[MAXN];

LL dp_results_alt[MAXN][2];

int compute_mask_alt(VPII edges, bool flag) {
    int mask_value = 0;
    for (int i = 0; i < size_of(edges); i++)
        for (int j = i + 1; j < size_of(edges); j++)
            if (edges[i].first != edges[j].first && edges[i].second != edges[j].second)
                for (int k = j + 1; k < size_of(edges); k++)
                    if (edges[i].first != edges[k].first && edges[j].first != edges[k].first
                        && edges[i].second != edges[k].second && edges[j].second != edges[k].second)
                        mask_value |= mask_map_vals_alt[(flag ? 126 : 0) ^ ((1 << edges[i].second) + (1 << edges[j].second) + (1 << edges[k].second))];
    return mask_value;
}

LL compute_power_alt(LL base, LL exponent) {
    if (exponent == 0) return 1;
    LL half_pow = compute_power_alt(base, exponent / 2);
    LL result = (half_pow * half_pow) % MOD;
    if (exponent & 1) result = (result * base) % MOD;
    return result;
}

int main() {
    sync_input_output
    int n;
    cin >> n;
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= n; j++)
            cin >> grid_vals_alt[i][j];
    int counter = 0;
    for (int i = 1; i <= 6; i++)
        for (int j = i + 1; j <= 6; j++)
            for (int k = j + 1; k <= 6; k++)
                mask_map_vals_alt[(1 << i) ^ (1 << j) ^ (1 << k)] = (1 << counter++);
    for (int i = n + 1; i <= 6; i++)
        grid_vals_alt[i][i] = 100;
    VPII edges;
    n = 6;
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= n; j++)
            edges.push_back({i, j});
    LL inv_100_alt = compute_power_alt(100, MOD - 2);
    for (int k = 0; k < 2; k++)
        for (int mask_idx = 0; mask_idx < (1 << 18); mask_idx++) {
            LL prob = 1;
            VPII selected_edges;
            for (int j = 0; j < 18; j++)
                if ((1 << j) & mask_idx) {
                    prob = (prob * grid_vals_alt[edges[j + k * 18].first][edges[j + k * 18].second]) % MOD * inv_100_alt % MOD;
                    selected_edges.push_back(edges[j + k * 18]);
                } else {
                    prob = (prob * (100 - grid_vals_alt[edges[j + k * 18].first][edges[j + k * 18].second])) % MOD * inv_100_alt % MOD;
                }
            int current_mask = compute_mask_alt(selected_edges, k);
            dp_results_alt[current_mask][k] = (dp_results_alt[current_mask][k] + prob) % MOD;
        }
    LL final_res_alt = 1;
    for (int i = 0; i < 20; i++)
        for (int j = 0; j < (1 << 20); j++)
            if ((1 << i) & j) {
                dp_results_alt[j][0] = (dp_results_alt[j][0] + dp_results_alt[j ^ (1 << i)][0]) % MOD;
            }
    for (int i = 0; i < (1 << 20); i++) {
        final_res_alt = (final_res_alt - dp_results_alt[i][0] * dp_results_alt[((1 << 20) - 1) ^ i][1]) % MOD;
    }
    final_res_alt = (final_res_alt + MOD) % MOD;
    cout << final_res_alt;
    return 0;
}
